import { Virtualizer } from '@tanstack/react-virtual';
import clsx from 'clsx';
import React from 'react';

import { DataTableV2Cell } from './DataTableV2Cell.js';
import {
  dataTableV2FirstBodyRowCSS,
  dataTableV2FirstColumnCSS,
  dataTableV2LastBodyRowCSS,
  dataTableV2LastColumnCSS,
} from './DataTableV2Rows.sty.js';
import { type Row } from '../hooks/useTable/types.js';

export function DataTableV2Body<T = unknown>(props: {
  rows: Row<T>[];
  rowVirtualizer: Virtualizer<HTMLDivElement, Element>;
  columnVirtualizer: Virtualizer<HTMLDivElement, Element>;
}): JSX.Element | null {
  const { rows, rowVirtualizer, columnVirtualizer } = props;

  return (
    <>
      {rowVirtualizer.getVirtualItems().map((virtualRow, rowIndex, allRows) =>
        columnVirtualizer
          .getVirtualItems()
          .map((virtualCell, cellIndex, allCells) => {
            const cell =
              rows[virtualRow.index].getAllCells()[virtualCell.index];

            return (
              <DataTableV2Cell
                key={`${virtualRow.key}-${virtualCell.key}`}
                cell={cell}
                measure={(node) => {
                  if (allCells[0]?.index === virtualCell.index) {
                    rowVirtualizer.measureElement(node);
                  }
                  if (allRows[0]?.index === virtualRow.index) {
                    columnVirtualizer.measureElement(node);
                  }
                }}
                rowIndex={virtualRow.index}
                columnIndex={virtualCell.index}
                style={{
                  ...cell.getGridPosition(virtualCell.index),
                }}
                className={clsx({
                  [dataTableV2FirstBodyRowCSS]: virtualRow.index === 0,
                  [dataTableV2LastBodyRowCSS]:
                    virtualRow.index === allRows.length - 1,
                  [dataTableV2FirstColumnCSS]: virtualCell.index === 0,
                  [dataTableV2LastColumnCSS]:
                    virtualCell.index === allCells.length - 1,
                })}
              />
            );
          }),
      )}
    </>
  );
}
DataTableV2Body.displayName = 'DataTableV2Body';
